import React, { useState, useEffect } from 'react';
import {
  XMarkIcon,
  CheckCircleIcon,
  XCircleIcon,
  BellIcon,
} from "@heroicons/react/24/outline";
import AdminSidebar from "../../AdminSidebar";
import api from '../../../services/api';

export default function AccountVerification() {
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [studentIdPreview, setStudentIdPreview] = useState(null);
  const [studyLoadPreview, setStudyLoadPreview] = useState(null);

  useEffect(() => {
    fetchUnverifiedUsers();
  }, []);

  const fetchUnverifiedUsers = async () => {
    try {
      setLoading(true);
      const response = await api.get('/auth/unverified-users');
      setUsers(response.data || []);
    } catch (error) {
      console.error('Error fetching users:', error);
    } finally {
      setLoading(false);
    }
  };

  const blobToDataUrl = (base64String) => {
    if (!base64String) return null;
    return `data:image/jpeg;base64,${base64String}`;
  };

  const handleViewDetails = (user) => {
    setSelectedUser(user);

    if (user.student_id_file) {
      setStudentIdPreview(blobToDataUrl(user.student_id_file));
    }

    if (user.study_load_file) {
      setStudyLoadPreview(blobToDataUrl(user.study_load_file));
    }

    setIsModalOpen(true);
  };

  const handleVerify = async (userId, status) => {
    try {
      await api.post(`/auth/verify-user/${userId}`, { status });
      fetchUnverifiedUsers();
      setIsModalOpen(false);
      setSelectedUser(null);
      setStudentIdPreview(null);
      setStudyLoadPreview(null);
      alert(`User ${status === 'approved' ? 'approved' : 'rejected'} successfully`);
    } catch (error) {
      console.error('Error verifying user:', error);
      alert('Failed to verify user');
    }
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setSelectedUser(null);
    setStudentIdPreview(null);
    setStudyLoadPreview(null);
  };

  return (
    <div className="flex h-screen bg-gradient-to-br from-gray-50 to-white">
      {/* Sidebar */}
      <AdminSidebar />

      {/* Main Content */}
      <div className="flex-1 overflow-hidden">
        {/* Header */}
        <div className="bg-white border-b shadow-sm">
          <div className="flex items-center justify-between px-8 py-6">
            <h2 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-600">
              Account Verification
            </h2>
            <div className="flex items-center gap-4">
              <button className="relative hover:bg-gray-100 p-2 rounded-lg transition-colors">
                <BellIcon className="h-6 w-6 text-gray-600" />
                <span className="absolute -top-1 -right-1 bg-red-500 w-2 h-2 rounded-full"></span>
              </button>
              <div className="text-right">
                <p className="text-sm font-medium text-gray-900">Pending Reviews</p>
                <p className="text-2xl font-bold text-blue-600">{users.length}</p>
              </div>
            </div>
          </div>
        </div>

        <div className="p-8 overflow-y-auto h-[calc(100vh-5rem)]">
          {loading ? (
            <div className="flex items-center justify-center h-full">
              <div className="text-center">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
                <p className="text-gray-600 mt-4">Loading users...</p>
              </div>
            </div>
          ) : users.length === 0 ? (
            <div className="flex items-center justify-center h-full">
              <div className="text-center">
                <CheckCircleIcon className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                <p className="text-lg text-gray-600 font-medium">No pending verifications</p>
              </div>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {users.map((user) => (
                <div
                  key={user.id}
                  className="bg-white rounded-2xl shadow-sm hover:shadow-md transition-all border border-gray-100 overflow-hidden"
                >
                  <div className="p-6">
                    <div className="flex items-start justify-between mb-4">
                      <div className="flex-1">
                        <h3 className="font-semibold text-lg text-gray-900">{user.full_name}</h3>
                        <p className="text-sm text-gray-500 mt-1 truncate">{user.email}</p>
                      </div>
                      <div className="w-10 h-10 bg-gradient-to-br from-blue-400 to-indigo-600 rounded-full flex-shrink-0 flex items-center justify-center text-white text-sm font-bold">
                        {user.full_name?.[0]?.toUpperCase()}
                      </div>
                    </div>

                    <div className="space-y-2 mb-6 bg-gray-50 p-3 rounded-lg">
                      <div className="flex justify-between text-sm">
                        <span className="text-gray-500">Course:</span>
                        <span className="font-medium text-gray-700">{user.course}</span>
                      </div>
                      <div className="flex justify-between text-sm">
                        <span className="text-gray-500">Year:</span>
                        <span className="font-medium text-gray-700">{user.year}</span>
                      </div>
                      <div className="flex justify-between text-sm">
                        <span className="text-gray-500">Role:</span>
                        <span className={`font-medium px-2 py-0.5 rounded text-xs ${
                          user.role === "Learner" ? "bg-blue-100 text-blue-700" :
                          user.role === "Tutor" ? "bg-purple-100 text-purple-700" :
                          "bg-green-100 text-green-700"
                        }`}>
                          {user.role}
                        </span>
                      </div>
                    </div>

                    <button
                      onClick={() => handleViewDetails(user)}
                      className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 text-white py-2.5 rounded-lg hover:from-blue-700 hover:to-indigo-700 transition-all font-medium"
                    >
                      View & Verify
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Verification Modal */}
      {isModalOpen && selectedUser && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl max-w-4xl w-full max-h-[90vh] overflow-hidden">
            {/* Modal Header */}
            <div className="bg-gradient-to-r from-blue-600 to-indigo-600 p-6 flex items-center justify-between">
              <div>
                <h2 className="text-2xl font-bold text-white">Verification Details</h2>
                <p className="text-blue-100 text-sm mt-1">Review user information and documents</p>
              </div>
              <button
                onClick={closeModal}
                className="text-white hover:bg-white/20 p-2 rounded-lg transition-colors"
              >
                <XMarkIcon className="w-6 h-6" />
              </button>
            </div>

            {/* Modal Content */}
            <div className="p-6 overflow-y-auto max-h-[calc(90vh-200px)]">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* User Information */}
                <div className="space-y-4">
                  <h3 className="font-semibold text-lg text-gray-800 mb-4">User Information</h3>

                  <div className="bg-gray-50 rounded-lg p-4 space-y-3">
                    <div>
                      <label className="text-xs text-gray-500 font-medium uppercase">Full Name</label>
                      <p className="font-medium text-gray-900 mt-1">{selectedUser.full_name}</p>
                    </div>

                    <div>
                      <label className="text-xs text-gray-500 font-medium uppercase">Email</label>
                      <p className="font-medium text-gray-900 mt-1">{selectedUser.email}</p>
                    </div>

                    <div>
                      <label className="text-xs text-gray-500 font-medium uppercase">Course</label>
                      <p className="font-medium text-gray-900 mt-1">{selectedUser.course}</p>
                    </div>

                    <div>
                      <label className="text-xs text-gray-500 font-medium uppercase">Year Level</label>
                      <p className="font-medium text-gray-900 mt-1">{selectedUser.year}</p>
                    </div>

                    <div>
                      <label className="text-xs text-gray-500 font-medium uppercase">Role</label>
                      <p className="font-medium text-gray-900 mt-1">{selectedUser.role}</p>
                    </div>
                  </div>
                </div>

                {/* Documents */}
                <div className="space-y-4">
                  <h3 className="font-semibold text-lg text-gray-800 mb-4">Submitted Documents</h3>

                  <div>
                    <label className="text-sm text-gray-600 font-medium mb-2 block">Student ID</label>
                    {studentIdPreview ? (
                      <div className="border-2 border-gray-200 rounded-lg overflow-hidden bg-gray-50">
                        <img
                          src={studentIdPreview}
                          alt="Student ID"
                          className="w-full object-contain max-h-48"
                        />
                      </div>
                    ) : (
                      <div className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center bg-gray-50">
                        <p className="text-gray-500 text-sm">No file uploaded</p>
                      </div>
                    )}
                  </div>

                  <div>
                    <label className="text-sm text-gray-600 font-medium mb-2 block">Study Load</label>
                    {studyLoadPreview ? (
                      <div className="border-2 border-gray-200 rounded-lg overflow-hidden bg-gray-50">
                        <img
                          src={studyLoadPreview}
                          alt="Study Load"
                          className="w-full object-contain max-h-48"
                        />
                      </div>
                    ) : (
                      <div className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center bg-gray-50">
                        <p className="text-gray-500 text-sm">No file uploaded</p>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>

            {/* Modal Footer */}
            <div className="bg-gray-50 p-6 flex gap-4 border-t">
              <button
                onClick={() => handleVerify(selectedUser.id, 'approved')}
                className="flex-1 bg-green-500 text-white py-3 rounded-lg hover:bg-green-600 transition-colors flex items-center justify-center gap-2 font-medium"
              >
                <CheckCircleIcon className="w-5 h-5" />
                <span>Approve Account</span>
              </button>
              <button
                onClick={() => handleVerify(selectedUser.id, 'rejected')}
                className="flex-1 bg-red-500 text-white py-3 rounded-lg hover:bg-red-600 transition-colors flex items-center justify-center gap-2 font-medium"
              >
                <XCircleIcon className="w-5 h-5" />
                <span>Reject</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
